import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { systemDb } from "@app/db";
import { googleAdsOperationsToday, syncAdConnection, type AdsSyncData } from "@app/core";
import { addDays, DEMO_ACCOUNT_ID, DEMO_CAMPAIGNS, localDay } from "@app/shared";
import { clean, createStore, createWorkspace, setup, signIn, teardown, type TestCtx } from "./helpers.js";

/**
 * The Google Ads demo (docs/ads-demo.md): a simulated account connected without any Google setting,
 * token or call; its figures generated by the same sync job that reads Google for real accounts; the
 * analytics endpoints; and the lines it never crosses (no production credentials, no Google call, no
 * other tenant's data, no real connection touched, no way to become a production connection).
 */

let ctx: TestCtx;
beforeAll(async () => (ctx = await setup()));
afterAll(async () => teardown(ctx));

/** The demo needs none of these: every test runs without them unless it says otherwise. */
const NO_PRODUCTION = { GOOGLE_ADS_CLIENT_ID: "", GOOGLE_ADS_CLIENT_SECRET: "", GOOGLE_ADS_ENABLED: "", GOOGLE_ADS_OAUTH_VERIFIED: "", GOOGLE_ADS_DEMO_ENABLED: "1" };

let headers: Record<string, string>;
let ws: string;
let storeId: string;
let base: string;
let fetched: string[];

beforeEach(async () => {
  await clean(ctx);
  ctx.setEnv(NO_PRODUCTION);
  // Any network call fails the test: the demo makes none.
  fetched = [];
  ctx.setFetch(async (input) => {
    fetched.push(String(input));
    throw new Error(`unexpected network call: ${String(input)}`);
  });
  const u = await signIn(ctx, "demo-owner", "owner@x.com");
  headers = u.headers;
  ws = await createWorkspace(ctx, headers);
  storeId = (await createStore(ws, "demo-shop.myshopify.com", ["read_orders"], { currency: "AUD", timezone: "Australia/Melbourne" })).id;
  base = `/workspaces/${ws}/stores/${storeId}/ads/google`;
});

const get = (url: string, h = headers) => ctx.app.inject({ method: "GET", url, headers: h });
const post = (url: string, payload: unknown = {}, h = headers) => ctx.app.inject({ method: "POST", url, headers: h, payload });

/** Connect the demo and run every sync job it queued, as the worker would. */
async function connectAndSync() {
  const res = await post(`${base}/demo/connect`);
  expect(res.statusCode).toBe(200);
  await runQueuedSyncs();
  return res.json();
}

async function runQueuedSyncs() {
  const jobs = ctx.deps.queues.sent.sync as unknown as AdsSyncData[];
  const mine = jobs.splice(0, jobs.length).filter((j) => j.kind === "ads");
  const results = [];
  for (const j of mine) results.push(await syncAdConnection(j.connectionId, j.since, j.until, ctx.deps.fetchImpl, { trigger: j.trigger, queues: ctx.deps.queues, coord: ctx.deps.coord }));
  return results;
}

const demoRow = () => systemDb.adConnection.findFirstOrThrow({ where: { storeId, isDemo: true } });

describe("the two modes' status", () => {
  it("says the demo is offered and production isn't set up, naming the settings it lacks (names only)", async () => {
    const res = await get(`${base}/status`);
    expect(res.statusCode).toBe(200);
    const s = res.json();
    expect(s.provider).toBe("google_ads");
    expect(s.demo).toMatchObject({ enabled: true, status: "not_connected", connection: null, account: null });
    expect(s.demo.badge).toContain("Not verified by Google");
    expect(s.production).toMatchObject({ configured: false, status: "not_connected", connections: [], missing: ["GOOGLE_ADS_CLIENT_ID", "GOOGLE_ADS_CLIENT_SECRET", "GOOGLE_ADS_ENABLED"] });
    expect(res.body).not.toContain("secret_value");
    // The real sign-in isn't offered in the demo's place.
    const start = await post(`/workspaces/${ws}/stores/${storeId}/ads/google/connect`);
    expect(start.statusCode).toBe(503);
    expect(start.json().error).toBe("not_configured");
  });

  it("lists the demo among the ad connections with what it is, and offers it on the ads list", async () => {
    const before = await get(`/workspaces/${ws}/stores/${storeId}/ads`);
    expect(before.json()).toMatchObject({ configured: { google: false }, demo: { google: true }, missing: { google: ["GOOGLE_ADS_CLIENT_ID", "GOOGLE_ADS_CLIENT_SECRET", "GOOGLE_ADS_ENABLED"] }, connections: [] });
    await post(`${base}/demo/connect`);
    const list = await get(`/workspaces/${ws}/stores/${storeId}/ads`);
    const [c] = list.json().connections;
    expect(c).toMatchObject({ provider: "google", accountId: DEMO_ACCOUNT_ID, accountName: "Demo Business Marketing", currency: "AUD", timezone: "Australia/Melbourne", demo: true, connectionType: "demo", verificationStatus: "simulated", connectionStatus: "demo_syncing", permission: null, grantedScopes: [], status: "active" });
    expect(typeof c.demoSeed).toBe("number");
    expect(list.body).not.toContain("Enc");
  });
});

describe("connecting the demo", () => {
  it("persists a demo connection without any token, queues its 90 days, and answers what it is", async () => {
    const res = await post(`${base}/demo/connect`);
    expect(res.statusCode).toBe(200);
    expect(res.json()).toMatchObject({
      success: true,
      provider: "google_ads",
      connection_type: "demo",
      connection_status: "demo_syncing",
      account: { id: DEMO_ACCOUNT_ID, name: "Demo Business Marketing", currency: "AUD", is_demo: true },
      verification_status: "simulated",
      message: "Demo account connected successfully",
      disclaimer: "No Google authorization or verification occurred.",
    });
    expect(res.json().demo).toMatchObject({ accountType: "Demo Advertising Account", authentication: "Simulated", dataSource: "Generated Sample Data", billingStatus: "Not Applicable — Demo", verification: "Not Verified by Google", country: "Australia" });
    expect(res.json().demo.permissions).toHaveLength(8);
    const row = await demoRow();
    expect(row).toMatchObject({ provider: "google", accountId: DEMO_ACCOUNT_ID, isDemo: true, accessTokenEnc: "", refreshTokenEnc: null, tokenKeyVersion: 0, enabled: true, status: "active", externalUserId: null });
    expect(row.demoSeed).toBeGreaterThan(0);
    expect(row.syncRequestedAt).not.toBeNull();
    const today = localDay(new Date(), "Australia/Melbourne");
    const jobs = ctx.deps.queues.sent.sync as unknown as AdsSyncData[];
    expect(jobs).toEqual([{ kind: "ads", connectionId: row.id, since: addDays(today, -89), until: today, trigger: "request" }]);
    expect(await systemDb.auditLog.count({ where: { action: "ads.demo_connected" } })).toBe(1);
    expect(fetched).toEqual([]);
  });

  it("is one per store: connecting again brings the same demo back, with the same seed", async () => {
    const first = (await post(`${base}/demo/connect`)).json();
    await runQueuedSyncs();
    await systemDb.adConnection.updateMany({ where: { storeId, isDemo: true }, data: { enabled: false } });
    const again = await post(`${base}/demo/connect`);
    expect(again.json().message).toBe("Demo account already connected");
    expect(again.json().demo.seed).toBe(first.demo.seed);
    expect(await systemDb.adConnection.count({ where: { storeId } })).toBe(1);
    expect((await demoRow()).enabled).toBe(true);
  });

  it("takes a seed to generate from, and refuses a bad one", async () => {
    const res = await post(`${base}/demo/connect`, { seed: 12345 });
    expect(res.json().demo.seed).toBe(12345);
    expect((await post(`${base}/demo/connect`, { seed: -1 })).statusCode).toBe(400);
  });

  it("isn't connected when the server doesn't offer it, and an existing one keeps working", async () => {
    await connectAndSync();
    ctx.setEnv({ ...NO_PRODUCTION, GOOGLE_ADS_DEMO_ENABLED: "" });
    const other = (await createStore(ws, "demo-two.myshopify.com", ["read_orders"], { currency: "AUD" })).id;
    const res = await post(`/workspaces/${ws}/stores/${other}/ads/google/demo/connect`);
    expect(res.statusCode).toBe(503);
    expect(res.json().error).toBe("demo_disabled");
    expect((await get(`${base}/status`)).json().demo).toMatchObject({ enabled: false, status: "connected_demo" });
    expect((await get(`${base}/analytics?preset=7d`)).statusCode).toBe(200);
  });

  it("needs the integrations permission; a member who may only view gets no further than reading", async () => {
    await connectAndSync();
    const viewer = await signIn(ctx, "demo-viewer", "viewer@x.com");
    await systemDb.membership.create({ data: { workspaceId: ws, userId: viewer.user.id, role: "custom", permissions: ["marketing.ads", "integrations.status"] } });
    expect((await get(`${base}/status`, viewer.headers)).statusCode).toBe(200);
    expect((await get(`${base}/analytics?preset=7d`, viewer.headers)).json().campaigns).toBeNull();
    expect((await get(`${base}/analytics/campaigns?preset=7d`, viewer.headers)).statusCode).toBe(403);
    for (const path of ["connect", "sync", "reset", "disconnect"]) expect((await post(`${base}/demo/${path}`, {}, viewer.headers)).statusCode).toBe(403);
  });
});

describe("the demo's figures", () => {
  it("are generated by the sync job without any network call, and feed the dashboard as a demo", async () => {
    await connectAndSync();
    const row = await demoRow();
    expect(row.lastSyncedAt).not.toBeNull();
    expect(row.syncRequestedAt).toBeNull();
    expect(row.historyFrom).toBe(addDays(localDay(new Date(), "Australia/Melbourne"), -89));
    expect(row.accountStatusDetail).toContain("not verified by Google");
    const days = await systemDb.adCampaignDaily.findMany({ where: { connectionId: row.id } });
    expect(days.length).toBeGreaterThan(400);
    expect(new Set(days.map((d) => d.campaignId)).size).toBe(DEMO_CAMPAIGNS.length);
    for (const d of days) {
      expect(d.clicks).toBeLessThanOrEqual(d.impressions);
      expect(Number(d.conversions)).toBeLessThanOrEqual(d.clicks);
    }
    expect(fetched).toEqual([]);
    expect((await get(`${base}/status`)).json().demo.status).toBe("connected_demo");

    const ov = await get(`/workspaces/${ws}/stores/${storeId}/overview?preset=7d`);
    expect(ov.statusCode).toBe(200);
    const ads = ov.json().modules.ads;
    expect(ads.demo).toBe(true);
    expect(ads.sales).toBeNull();
    expect(ads.shareOfSales).toBeNull();
    expect(ads.accounts[0]).toMatchObject({ accountId: DEMO_ACCOUNT_ID, demo: true, counted: true });
    expect(ads.byProvider[0]).toMatchObject({ provider: "google", demo: true });
    expect(ads.byProvider[0].spend).toBeGreaterThan(0);
    // The downloadable report names the demo's rows as simulated.
    const csv = await get(`/workspaces/${ws}/stores/${storeId}/export?section=ads&preset=7d`);
    expect(csv.statusCode).toBe(200);
    expect(csv.body).toContain("Google Ads (demo, simulated)");
    expect(csv.body).toContain("Search Advertising");
  });

  it("answer the live Google Ads report without Google", async () => {
    await connectAndSync();
    const row = await demoRow();
    const today = localDay(new Date(), "Australia/Melbourne");
    const res = await get(`/workspaces/${ws}/stores/${storeId}/ads/google/report?connection=${row.id}&level=campaign&from=${addDays(today, -7)}&to=${today}`);
    expect(res.statusCode).toBe(200);
    // As Google's report: only campaigns with activity in the dates (Website Traffic was paused 20 days before the demo).
    const names = res.json().report.rows.map((r: { name: string }) => r.name);
    expect(names).not.toContain("Website Traffic");
    expect(names).toHaveLength(DEMO_CAMPAIGNS.length - 1);
    expect(res.json().report.rows[0]).toHaveProperty("dailyBudget");
    // A real account's campaign fields: Google's primary status and its reasons, and the budget's period.
    const search = res.json().report.rows.find((r: { id: string }) => r.id === "demo-c2");
    expect(search).toMatchObject({ primaryStatus: "LIMITED", primaryStatusReasons: ["BUDGET_CONSTRAINED"], budgetPeriod: "DAILY", totalBudget: null });
    expect(fetched).toEqual([]);
  });

  it("open a campaign's ad groups, a Performance Max campaign's asset groups and an ad group's ads, all without Google", async () => {
    await connectAndSync();
    const row = await demoRow();
    const today = localDay(new Date(), "Australia/Melbourne");
    const report = (q: Record<string, string>) => get(`/workspaces/${ws}/stores/${storeId}/ads/google/report?${new URLSearchParams({ connection: row.id, from: addDays(today, -7), to: today, ...q })}`);
    const campaign = (await report({ level: "campaign" })).json().report.rows.find((r: { id: string }) => r.id === "demo-c2");
    const groups = await report({ level: "ad_group", campaign: "demo-c2" });
    expect(groups.statusCode).toBe(200);
    expect(groups.json().report.rows.map((r: { id: string }) => r.id).sort()).toEqual(["demo-c2-broad", "demo-c2-core"]);
    // Split from the campaign: its ad groups add up to it.
    expect(groups.json().report.totals.spend).toBeCloseTo(campaign.spend, 2);
    const ads = await report({ level: "ad", campaign: "demo-c2", adGroup: "demo-c2-core" });
    expect(ads.statusCode).toBe(200);
    expect(ads.json().report.rows.length).toBeGreaterThanOrEqual(2);
    expect(ads.json().report.rows.every((r: { adGroupId: string; adType: string }) => r.adGroupId === "demo-c2-core" && r.adType === "RESPONSIVE_SEARCH_AD")).toBe(true);
    const assets = await report({ level: "asset_group", campaign: "demo-c7" });
    expect(assets.json().report.rows).toHaveLength(2);
    // The demo's ids only: a Google-shaped id isn't one of the demo's.
    expect((await report({ level: "ad_group", campaign: "12345" })).statusCode).toBe(400);
    expect(fetched).toEqual([]);
  });

  it("keywords and search terms, generated: no Google call, no operation spent, and no daily cap", async () => {
    await connectAndSync();
    const row = await demoRow();
    const today = localDay(new Date(), "Australia/Melbourne");
    const report = (q: Record<string, string>) => get(`/workspaces/${ws}/stores/${storeId}/ads/google/report?${new URLSearchParams({ connection: row.id, from: addDays(today, -30), to: today, ...q })}`);
    const before = await googleAdsOperationsToday(ctx.deps.coord);
    const keywords = await report({ level: "keyword" });
    expect(keywords.statusCode).toBe(200);
    const rows = keywords.json().report.rows as Array<{ campaignId: string; matchType: string; qualityScore: number }>;
    expect(rows.length).toBeGreaterThan(0);
    expect(new Set(rows.map((r) => r.campaignId))).toEqual(new Set(["demo-c2", "demo-c5"]));
    expect(rows.every((r) => ["EXACT", "PHRASE", "BROAD"].includes(r.matchType) && r.qualityScore >= 1 && r.qualityScore <= 10)).toBe(true);
    const inGroup = await report({ level: "keyword", campaign: "demo-c2", adGroup: "demo-c2-core" });
    expect(inGroup.json().report.rows.every((r: { adGroupId: string }) => r.adGroupId === "demo-c2-core")).toBe(true);
    const terms = await report({ level: "search_term", campaign: "demo-c7" });
    expect(terms.statusCode).toBe(200);
    expect(terms.json().report.rows.length).toBeGreaterThan(0);
    // The campaign's own figures on top: more than its listed terms.
    const listed = terms.json().report.rows.reduce((a: number, r: { spend: number }) => a + r.spend, 0);
    expect(terms.json().report.totals.spend).toBeGreaterThan(listed);
    // Past the 25 a day a real account may read from Google: the demo costs nothing, so nothing holds it back.
    for (let i = 1; i <= 24; i++) expect((await report({ level: i % 2 ? "search_term" : "keyword", from: addDays(today, -30 - i) })).statusCode).toBe(200);
    expect(await googleAdsOperationsToday(ctx.deps.coord)).toBe(before);
    expect(fetched).toEqual([]);
  });

  it("the analytics: consistent figures, every section, the demo said on it", async () => {
    await connectAndSync();
    const res = await get(`${base}/analytics?preset=30d`);
    expect(res.statusCode).toBe(200);
    const a = res.json();
    expect(a.account).toMatchObject({ accountId: DEMO_ACCOUNT_ID, demo: true, connectionType: "demo", verificationStatus: "simulated", status: "connected_demo", currency: "AUD" });
    expect(a.disclaimer).toContain("Simulated");
    const o = a.overview.current;
    expect(o.ctr).toBeCloseTo(o.clicks / o.impressions, 10);
    expect(o.cpc).toBeCloseTo(o.spend / o.clicks, 2);
    expect(o.conversionRate).toBeCloseTo(o.conversions / o.clicks, 10);
    expect(o.costPerConversion).toBeCloseTo(o.spend / o.conversions, 2);
    expect(o.roas).toBeCloseTo(o.conversionValue / o.spend, 10);
    expect(a.series.day).toHaveLength(30);
    expect(a.series.week.length).toBeGreaterThanOrEqual(5);
    expect(a.series.day.reduce((s: number, d: { spend: number }) => s + d.spend, 0)).toBeCloseTo(o.spend, 1);
    expect(a.campaigns).toHaveLength(DEMO_CAMPAIGNS.length);
    expect(a.campaigns[0].dailyBudget).toBeGreaterThan(0);
    expect(a.conversions.series).toHaveLength(30);
    expect(a.conversions.top.length).toBeGreaterThan(0);
    const devices = a.devices.reduce((s: number, d: { impressions: number }) => s + d.impressions, 0);
    expect(devices).toBe(o.impressions);
    expect(a.audience.age.length).toBe(7);
    expect(a.audience.countries[0].name).toBe("Australia");
    expect(a.audience.segments.length).toBe(6);
    expect(Array.isArray(a.recommendations)).toBe(true);
    expect(a.recommendations.every((r: { simulated: boolean }) => r.simulated)).toBe(true);
    expect(a.combined.days).toHaveLength(30);
    expect(a.combined.totals.orders).toBeGreaterThanOrEqual(a.combined.totals.adOrders);
    expect(a.combined.note).toContain("Not your Shopify sales");
    // Compared with the 30 days before, which the demo has as well.
    expect(a.overview.previous).not.toBeNull();
    // Its campaigns' types, statuses and budgets are the generator's; the sync stored the same facts, as it does a real account's.
    expect(a.campaignSettings).toEqual({ source: "generated", asOf: null });
    expect(a.campaigns.every((c: { primaryStatus: string | null; budgetPeriod: string | null }) => c.primaryStatus !== null && c.budgetPeriod === "DAILY")).toBe(true);
    const stored = await systemDb.adCampaign.findFirstOrThrow({ where: { connectionId: (await demoRow()).id, campaignId: "demo-c2" } });
    expect(stored).toMatchObject({ channelType: expect.any(String), primaryStatus: expect.any(String), budgetPeriod: "DAILY" });
    expect(Number(stored.budgetAmount)).toBe(a.campaigns.find((c: { id: string }) => c.id === "demo-c2").dailyBudget);
    expect(fetched).toEqual([]);
  });

  it("a real account's analytics: each campaign's type, status and budget as its last sync stored them, never made up", async () => {
    const real = await systemDb.adConnection.create({
      data: { workspaceId: ws, storeId, provider: "google", accountId: "1234567890", accountName: "Real", currency: "AUD", timezone: "UTC", accessTokenEnc: "v1.real", tokenKeyVersion: 1, historyFrom: "2026-01-01", syncedThrough: localDay(new Date(), "UTC") },
    });
    const today = localDay(new Date(), "UTC");
    const [from, to] = [addDays(today, -3), addDays(today, -1)];
    const at = { workspaceId: ws, storeId, connectionId: real.id, provider: "google", accountId: "1234567890" };
    for (const day of [from, addDays(from, 1), to]) {
      for (const [campaignId, spend] of [["7", 8], ["8", 20], ["9", 1]] as const) {
        await systemDb.adCampaignDaily.create({ data: { ...at, campaignId, campaignName: `Campaign ${campaignId}`, day, spend, impressions: 100, clicks: 4 } });
      }
    }
    const read = new Date("2026-10-30T06:00:00Z");
    await systemDb.adCampaign.createMany({
      data: [
        { ...at, campaignId: "7", name: "Search - brand", status: "ENABLED", channelType: "SEARCH", primaryStatus: "LIMITED", primaryStatusReasons: ["BUDGET_CONSTRAINED"], budgetPeriod: "DAILY", budgetAmount: 10, checkedAt: read },
        { ...at, campaignId: "8", name: "PMax launch", status: "ENABLED", channelType: "PERFORMANCE_MAX", primaryStatus: "ELIGIBLE", budgetPeriod: "CUSTOM_PERIOD", budgetAmount: 500, checkedAt: new Date("2026-10-30T05:00:00Z") },
        // Read before its facts were: its status only.
        { ...at, campaignId: "9", name: "Old", status: "PAUSED", checkedAt: new Date("2026-10-29T05:00:00Z") },
        // No figures in the dates: not listed at zero.
        { ...at, campaignId: "10", name: "Idle", status: "ENABLED", channelType: "DISPLAY", budgetPeriod: "DAILY", budgetAmount: 3, checkedAt: read },
      ],
    });
    const res = await get(`${base}/analytics?preset=custom&from=${from}&to=${to}&connection=${real.id}`);
    expect(res.statusCode).toBe(200);
    const a = res.json();
    expect(a.account).toMatchObject({ demo: false, connectionType: "production" });
    expect(a.campaignSettings).toEqual({ source: "synced", asOf: read.toISOString() });
    const by = Object.fromEntries(a.campaigns.map((c: Record<string, unknown>) => [c.id, c]));
    expect(Object.keys(by).sort()).toEqual(["7", "8", "9"]);
    // A daily budget: today's, paced over the days the campaign ran in the dates (3 × $10 = $30, $24 of it spent).
    expect(by["7"]).toMatchObject({ name: "Search - brand", type: "SEARCH", status: "ENABLED", primaryStatus: "LIMITED", primaryStatusReasons: ["BUDGET_CONSTRAINED"], budgetPeriod: "DAILY", dailyBudget: 10, totalBudget: null, activeDays: 3, budget: 30, budgetUse: 0.8 });
    // A campaign total budget covers its own dates, not these: stated, never paced.
    expect(by["8"]).toMatchObject({ type: "PERFORMANCE_MAX", primaryStatus: "ELIGIBLE", budgetPeriod: "CUSTOM_PERIOD", totalBudget: 500, dailyBudget: null, budget: null, budgetUse: null });
    // Not read yet: nothing in their place.
    expect(by["9"]).toMatchObject({ type: null, status: "PAUSED", primaryStatus: null, primaryStatusReasons: [], budgetPeriod: null, dailyBudget: null, budget: null });
    // A paused campaign gets no recommendation; the table filters by the stored type.
    const searchOnly = await get(`${base}/analytics/campaigns?preset=custom&from=${from}&to=${to}&connection=${real.id}&type=SEARCH`);
    expect(searchOnly.json().rows.map((c: { id: string }) => c.id)).toEqual(["7"]);
  });

  it("the campaign table: search, filters, sorting, pages and dates", async () => {
    await connectAndSync();
    const today = localDay(new Date(), "Australia/Melbourne");
    const page = (q: string) => get(`${base}/analytics/campaigns?preset=30d&${q}`).then((r) => r.json());
    const all = await page("pageSize=5");
    expect(all).toMatchObject({ total: DEMO_CAMPAIGNS.length, page: 1, pages: 2, pageSize: 5 });
    expect(all.rows).toHaveLength(5);
    expect(all.rows.map((c: { spend: number }) => c.spend)).toEqual([...all.rows.map((c: { spend: number }) => c.spend)].sort((x, y) => y - x));
    expect((await page("pageSize=5&page=2")).rows).toHaveLength(2);
    expect((await page("q=search")).rows.map((c: { name: string }) => c.name)).toEqual(["Search Advertising"]);
    expect((await page("status=PAUSED")).rows.map((c: { name: string }) => c.name)).toEqual(["Website Traffic"]);
    expect((await page("type=DISPLAY")).total).toBe(2);
    const byName = await page("sort=name&dir=asc");
    expect(byName.rows[0].name).toBe("Brand Awareness");
    // Dates: a custom week counts only those days.
    const week = await get(`${base}/analytics/campaigns?preset=custom&from=${addDays(today, -7)}&to=${addDays(today, -1)}`);
    expect(week.json().rows.find((c: { id: string }) => c.id === "demo-c2").activeDays).toBe(7);
    expect((await get(`${base}/analytics/campaigns?preset=custom&from=${today}&to=${addDays(today, -3)}`)).statusCode).toBe(400);
  });

  it("empty dates and unknown connections don't break anything", async () => {
    await connectAndSync();
    // Long before the demo's history: zeros, and every rate undefined rather than a division error.
    const res = await get(`${base}/analytics?preset=custom&from=2021-01-04&to=2021-01-10`);
    expect(res.statusCode).toBe(200);
    const a = res.json();
    expect(a.overview.current).toMatchObject({ spend: 0, impressions: 0, clicks: 0, ctr: null, cpc: null, roas: null, conversionRate: null });
    expect(a.overview.previous).toBeNull();
    expect(a.coverage.complete).toBe(false);
    expect(a.series.day).toHaveLength(7);
    expect(a.devices.every((d: { spend: number; share: number | null }) => d.spend === 0 && d.share === null)).toBe(true);
    expect(a.recommendations).toEqual([]);
    expect((await get(`${base}/analytics?preset=7d&connection=nope`)).statusCode).toBe(404);
  });
});

describe("sync, reset and disconnect", () => {
  it("Sync demo data queues one catch-up at a time; two syncs of the same days never double a row, and with the coordinator one waits for the other", async () => {
    await connectAndSync();
    const first = await post(`${base}/demo/sync`);
    expect(first.statusCode).toBe(200);
    expect(first.json()).toMatchObject({ queued: true, status: "demo_syncing" });
    const second = await post(`${base}/demo/sync`);
    expect(second.json().queued).toBe(false);
    const row = await demoRow();
    const job = (ctx.deps.queues.sent.sync as unknown as AdsSyncData[]).find((j) => j.kind === "ads")!;
    // The same job run twice at once, as a redelivered message would be. Without the coordinator (an ops
    // script, or a coordinator that didn't answer) the two write side by side, and still never double a row.
    const sync = (withCoord: boolean) =>
      syncAdConnection(row.id, job.since, job.until, ctx.deps.fetchImpl, { trigger: "request", queues: ctx.deps.queues, ...(withCoord ? { coord: ctx.deps.coord } : {}) });
    expect(await Promise.all([sync(false), sync(false)])).toMatchObject([{ skipped: false }, { skipped: false }]);
    // With it, one reads the days; the other, finding it running, reads nothing ("busy"), and sent again
    // by the worker once the first has ended, it syncs.
    const both = await Promise.all([sync(true), sync(true)]);
    expect(both.filter((r) => r.skipped && r.reason === "busy")).toHaveLength(1);
    expect(both.filter((r) => !r.skipped)).toHaveLength(1);
    expect(await sync(true)).toMatchObject({ skipped: false });
    const days = await systemDb.adCampaignDaily.findMany({ where: { connectionId: row.id }, select: { campaignId: true, day: true } });
    expect(new Set(days.map((d) => `${d.campaignId}|${d.day}`)).size).toBe(days.length);
    expect((await get(`${base}/status`)).json().demo.status).toBe("connected_demo");
    expect(await systemDb.auditLog.count({ where: { action: "ads.demo_synced" } })).toBe(2);
    expect(fetched).toEqual([]);
  });

  it("Reset demo data generates different figures from a new seed, and touches no real connection", async () => {
    const connected = await connectAndSync();
    const row = await demoRow();
    const spendBefore = await systemDb.adCampaignDaily.aggregate({ where: { connectionId: row.id }, _sum: { spend: true } });
    // A real Google Ads account on the same store, with a day of its own.
    const real = await systemDb.adConnection.create({
      data: { workspaceId: ws, storeId, provider: "google", accountId: "1234567890", accountName: "Real", currency: "AUD", accessTokenEnc: "v1.real", tokenKeyVersion: 1, historyFrom: "2026-01-01", syncedThrough: "2026-01-01" },
    });
    await systemDb.adCampaignDaily.create({ data: { workspaceId: ws, storeId, connectionId: real.id, provider: "google", accountId: "1234567890", campaignId: "7", campaignName: "Real", day: "2026-01-01", spend: 5, impressions: 10, clicks: 1 } });

    const reset = await post(`${base}/demo/reset`);
    expect(reset.statusCode).toBe(200);
    expect(reset.json().seed).not.toBe(connected.demo.seed);
    expect(await systemDb.adCampaignDaily.count({ where: { connectionId: row.id } })).toBe(0);
    await runQueuedSyncs();
    const spendAfter = await systemDb.adCampaignDaily.aggregate({ where: { connectionId: row.id }, _sum: { spend: true } });
    expect(Number(spendAfter._sum.spend)).not.toBe(Number(spendBefore._sum.spend));
    expect(await systemDb.adCampaignDaily.count({ where: { connectionId: real.id } })).toBe(1);
    expect(await systemDb.adConnection.findUnique({ where: { id: real.id } })).toMatchObject({ accessTokenEnc: "v1.real", isDemo: false });
    expect((await post(`${base}/demo/reset`, { seed: 777 })).json().seed).toBe(777);
    expect(await systemDb.auditLog.count({ where: { action: "ads.demo_reset" } })).toBe(2);
    // A real connection can't be reset through the demo endpoints.
    expect((await post(`/workspaces/${ws}/stores/${storeId}/ads/google/demo/reset`)).json().seed).toBeDefined();
  });

  it("Disconnect deletes the demo and its figures, nothing else, and says nothing was handed back", async () => {
    await connectAndSync();
    const row = await demoRow();
    const real = await systemDb.adConnection.create({
      data: { workspaceId: ws, storeId, provider: "google", accountId: "1234567890", accountName: "Real", currency: "AUD", accessTokenEnc: "v1.real", tokenKeyVersion: 1 },
    });
    const res = await post(`${base}/demo/disconnect`);
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ok: true, provider: "google_ads", connection_status: "disconnected", retention: "delete" });
    expect(await systemDb.adConnection.findUnique({ where: { id: row.id } })).toBeNull();
    expect(await systemDb.adCampaignDaily.count({ where: { connectionId: row.id } })).toBe(0);
    expect(await systemDb.adConnection.findUnique({ where: { id: real.id } })).not.toBeNull();
    expect(await systemDb.auditLog.count({ where: { action: "ads.demo_disconnected" } })).toBe(1);
    expect((await get(`${base}/status`)).json().demo.status).toBe("not_connected");
    expect((await post(`${base}/demo/disconnect`)).statusCode).toBe(404);
    expect((await get(`${base}/analytics?preset=7d`)).json().error).toBe("no_demo");
    expect(fetched).toEqual([]);
  });

  it("the ordinary Disconnect on the connections list does the same for a demo", async () => {
    await connectAndSync();
    const row = await demoRow();
    const res = await ctx.app.inject({ method: "DELETE", url: `/workspaces/${ws}/stores/${storeId}/ads/connections/${row.id}`, headers });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ok: true });
    expect(await systemDb.adConnection.count({ where: { storeId } })).toBe(0);
  });

  it("the demo survives a page reload: the status and the seed are what was written", async () => {
    const connected = await connectAndSync();
    for (let i = 0; i < 2; i++) {
      const s = (await get(`${base}/status`)).json();
      expect(s.demo.status).toBe("connected_demo");
      expect(s.demo.account.seed).toBe(connected.demo.seed);
      expect(s.demo.connection.id).toBe(connected.demo.connectionId);
    }
  });
});

describe("what the demo can't do", () => {
  it("never becomes a production connection, whatever a browser sends", async () => {
    const res = await post(`${base}/demo/connect`, { connection_type: "production", isDemo: false, demo: false, verification_status: "approved" });
    expect(res.json()).toMatchObject({ connection_type: "demo", verification_status: "simulated" });
    const row = await demoRow();
    const patch = await ctx.app.inject({ method: "PATCH", url: `/workspaces/${ws}/stores/${storeId}/ads/connections/${row.id}`, headers, payload: { demo: false, isDemo: false, connectionType: "production", enabled: true } });
    expect(patch.statusCode).toBe(200);
    expect(patch.json().connection).toMatchObject({ demo: true, connectionType: "demo", verificationStatus: "simulated" });
    expect((await demoRow()).isDemo).toBe(true);
    // The real sign-in, once set up, still has nothing to do with the demo row.
    ctx.setEnv({ ...NO_PRODUCTION, GOOGLE_ADS_CLIENT_ID: "g_client", GOOGLE_ADS_CLIENT_SECRET: "g_secret", GOOGLE_ADS_ENABLED: "1" });
    const s = (await get(`${base}/status`)).json();
    expect(s.production).toMatchObject({ configured: true, missing: [], status: "not_connected", connections: [] });
    expect(s.demo.status).toBe("demo_syncing");
  });

  it("stays inside its workspace: another workspace's member reaches none of it", async () => {
    await connectAndSync();
    const row = await demoRow();
    const other = await signIn(ctx, "demo-other", "other@x.com");
    const ws2 = await createWorkspace(ctx, other.headers, "Other Co");
    const store2 = (await createStore(ws2, "other-shop.myshopify.com", ["read_orders"])).id;
    // The demo's store, through the other person's session: not a member, so nothing is there.
    for (const url of [`${base}/status`, `${base}/demo/account`, `${base}/analytics?preset=7d`, `${base}/analytics/campaigns?preset=7d`]) expect((await get(url, other.headers)).statusCode).toBe(404);
    for (const path of ["sync", "reset", "disconnect"]) expect((await post(`${base}/demo/${path}`, {}, other.headers)).statusCode).toBe(404);
    // Their own store naming the demo's connection id: not theirs either.
    expect((await get(`/workspaces/${ws2}/stores/${store2}/ads/google/analytics?preset=7d&connection=${row.id}`, other.headers)).statusCode).toBe(404);
    expect((await get(`/workspaces/${ws2}/stores/${store2}/ads/google/status`, other.headers)).json().demo.status).toBe("not_connected");
    expect(await systemDb.adConnection.count({ where: { id: row.id } })).toBe(1);
  });
});
